:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #172623;
  color: #f7f3e8;
  --ink: #172623;
  --green: #b8df74;
  --cream: #f7f3e8;
  --muted: #afc0b2;
  --orange: #f0a45a;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 0%, #355047 0, #23372f 42%, #172623 78%);
}

.board {
  width: min(100%, 640px);
  padding: clamp(24px, 6vw, 48px);
  border: 2px solid #506b58;
  border-radius: 12px;
  background: #263a32;
  box-shadow: 0 14px 0 #101a17, 0 28px 70px #0c151255;
  text-align: center;
}

.eyebrow, .result-label {
  margin: 0;
  color: var(--green);
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1 {
  margin: 10px 0 12px;
  font-size: clamp(2rem, 7vw, 3rem);
  line-height: 1.1;
  letter-spacing: -0.04em;
}

.instructions { max-width: 430px; margin: 0 auto; color: var(--muted); line-height: 1.6; }
.game { margin-top: 32px; padding: 22px; border: 1px solid #506b58; border-radius: 10px; background: #1d3029; }
.status-row { display: flex; justify-content: space-between; gap: 12px; color: var(--muted); font-weight: 700; }
.dice-tray { display: flex; justify-content: center; flex-wrap: wrap; gap: 12px; margin: 26px 0 12px; }

.die {
  display: grid;
  width: clamp(48px, 12vw, 68px);
  aspect-ratio: 1;
  place-items: center;
  padding: 0;
  border: 3px solid #d8d1bb;
  border-radius: 9px;
  background: var(--cream);
  color: var(--ink);
  font-size: clamp(1.8rem, 7vw, 2.5rem);
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
  box-shadow: 0 5px 0 #b9b29e;
  transition: transform 120ms ease, box-shadow 120ms ease, border-color 120ms ease, background 120ms ease;
}
.die:hover { transform: translateY(-3px); box-shadow: 0 8px 0 #b9b29e; }
.die:active { transform: translateY(3px); box-shadow: 0 2px 0 #b9b29e; }
.die:focus-visible, .button:focus-visible { outline: 3px solid var(--orange); outline-offset: 4px; }
.die.is-held { border-color: var(--green); background: var(--green); box-shadow: 0 5px 0 #86aa4c; }
.die:disabled { cursor: default; }
.die:disabled:hover { transform: none; }

.hint { margin: 14px 0 22px; color: var(--muted); font-size: 0.95rem; }
.actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 12px; }
.button { min-height: 48px; padding: 0 22px; border: 2px solid transparent; border-radius: 7px; font: inherit; font-weight: 800; cursor: pointer; transition: transform 120ms ease, filter 120ms ease, box-shadow 120ms ease; }
.button:hover { filter: brightness(1.08); transform: translateY(-2px); }
.button:active { transform: translateY(2px); }
.button-primary { background: var(--green); color: var(--ink); box-shadow: 0 4px 0 #86aa4c; }
.button-primary:active { box-shadow: 0 1px 0 #86aa4c; }
.button-secondary { border-color: #66816c; background: transparent; color: var(--cream); }
.result { display: grid; gap: 5px; margin: 26px auto 0; }
.result strong { color: var(--orange); font-size: 1.55rem; }
footer { margin-top: 24px; color: #91a697; font-size: 0.85rem; letter-spacing: 0.04em; }

@media (max-width: 420px) {
  .game { padding: 18px 12px; }
  .dice-tray { gap: 9px; }
  .status-row { font-size: 0.9rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; }
}

const diceTray = document.querySelector("#dice");
const rollButton = document.querySelector("#roll-button");
const newRoundButton = document.querySelector("#new-round-button");
const roundStatus = document.querySelector("#round-status");
const rollStatus = document.querySelector("#roll-status");
const handName = document.querySelector("#hand-name");

let dice = Array(5).fill(1);
let held = Array(5).fill(false);
let rollsLeft = 2;
let started = false;

function handFor(values) {
  const counts = values.reduce((map, value) => map.set(value, (map.get(value) || 0) + 1), new Map());
  const groups = [...counts.values()].sort((a, b) => b - a);
  const unique = [...counts.keys()].sort((a, b) => a - b);
  const straight = unique.length === 5 && (unique.every((value, i) => i === 0 || value === unique[i - 1] + 1) || unique.join(",") === "1,2,3,4,6");

  if (groups[0] === 5) return "Five of a kind";
  if (groups[0] === 4) return "Four of a kind";
  if (groups[0] === 3 && groups[1] === 2) return "Full house";
  if (straight) return "Straight";
  if (groups[0] === 3) return "Three of a kind";
  if (groups[0] === 2 && groups[1] === 2) return "Two pair";
  if (groups[0] === 2) return "Pair";
  return "High dice";
}

function render() {
  diceTray.replaceChildren();
  dice.forEach((value, index) => {
    const die = document.createElement("button");
    die.type = "button";
    die.className = `die${held[index] ? " is-held" : ""}`;
    die.textContent = String(value);
    die.setAttribute("aria-label", `Die ${index + 1}: ${value}${held[index] ? ", held" : ", not held"}`);
    die.setAttribute("aria-pressed", String(held[index]));
    die.disabled = !started || rollsLeft === 0;
    die.addEventListener("click", () => {
      held[index] = !held[index];
      render();
    });
    diceTray.append(die);
  });

  rollStatus.textContent = `Rolls left: ${rollsLeft}`;
  rollButton.textContent = started ? (rollsLeft ? "Reroll unheld dice" : "Round complete") : "Roll dice";
  rollButton.disabled = started && rollsLeft === 0;
  newRoundButton.hidden = rollsLeft !== 0;
  roundStatus.textContent = !started ? "Ready to roll" : rollsLeft ? "Choose dice to hold" : "Round complete";
  handName.textContent = started ? (rollsLeft === 0 ? handFor(dice) : "Rolling…") : "—";
}

rollButton.addEventListener("click", () => {
  if (!started) {
    started = true;
  } else if (rollsLeft === 0) {
    return;
  }
  dice = dice.map((value, index) => held[index] ? value : Math.floor(Math.random() * 6) + 1);
  rollsLeft -= 1;
  if (rollsLeft === 0) held.fill(true);
  render();
});

newRoundButton.addEventListener("click", () => {
  dice = Array(5).fill(1);
  held = Array(5).fill(false);
  rollsLeft = 2;
  started = false;
  render();
});

render();
